window.CardComparisonIndex=[{"key":"beam","title":"棒・梁の選び方（CROD・CONROD・CBAR・CBEAM）","summary":"軸力・ねじりだけを扱う棒ならCRODかCONROD。曲げと横せん断も扱う梁ならCBARかCBEAMです。","cards":["CROD","CONROD","CBAR","CBEAM","PROD","PBAR","PBARL","PBEAM","PBEAML"]},{"key":"beam-properties","title":"PBAR・PBARL・PBEAM・PBEAML","summary":"PBAR／PBEAMは断面定数を直接指定し、PBARL／PBEAMLは用意された断面形式と寸法から特性を定義します。BAR系とBEAM系の対応、応力を回復する位置も合わせて確認します。","cards":["PBAR","PBARL","PBEAM","PBEAML","MAT1"]},{"key":"shell-elements","title":"CQUAD4・CTRIA3・CQUAD8・CTRIA6","summary":"四角形／三角形と、中間節点の有無を区別します。節点数が多い要素ほど常に優れるとは限らず、曲率、曲げ、メッシュ品質、出力位置をそろえて判断します。","cards":["CQUAD4","CTRIA3","CQUAD8","CTRIA6","PSHELL","PCOMP"]},{"key":"shell-properties","title":"PSHELLとPCOMP","summary":"PSHELLは板の面内・曲げ・横せん断などの特性を指定します。PCOMPは層ごとの材料・厚さ・角度を積み重ねて積層板を定義します。PSHELLを等方材専用、PCOMPを単なる厚さ指定と理解しないことが要点です。","cards":["PSHELL","PCOMP","MAT1","MAT8","CQUAD4"]},{"key":"solid-elements","title":"CTETRAの4／10節点・CHEXAの8／20節点","summary":"CTETRAは四面体、CHEXAは六面体です。中間節点の有無により形状と変位の補間が変わります。『ソリッドだから詳細で正確』とはせず、評価量と変形モードに合う分割を選びます。","cards":["CTETRA","CHEXA","PSOLID"]},{"key":"rigid-interpolation","title":"支持・拘束の選び方（SPC・RBE2・RBE3・MPC）","summary":"支持はSPC、剛な結合はRBE2、参照点と周辺の重み付き補間はRBE3、独自の線形拘束式はMPCです。","cards":["SPC","RBE2","RBE3","MPC","SPC1","CASE_SPC","CASE_MPC","CASE_SPCFORCES","CBUSH"]},{"key":"constraints","title":"SPC・SPC1・SPCD","summary":"SPCとSPC1は拘束する自由度を指定し、SPCDは強制変位などの値を荷重側で指定します。SPCDは、通常、対象自由度を選択済みのSPC／SPC1にも含めて使います。","cards":["SPC","SPC1","SPCD","SPCADD","CASE_SPC","CASE_LOAD"]},{"key":"springs","title":"CELAS1・CELAS2・CBUSH","summary":"CELAS1／CELAS2は指定した二つの自由度を結ぶスカラーばねです。CBUSHは要素座標系に基づく並進・回転方向のばね・減衰特性を持つ接合部として使います。","cards":["CELAS1","CELAS2","PELAS","CBUSH","PBUSH"]},{"key":"mass","title":"CONM1・CONM2・CMASS系","summary":"CONM2は質量・重心偏心・慣性モーメントを指定し、CONM1は節点の6×6対称質量行列を直接定義します。CMASS系はスカラー成分の質量として役割を分けます。","cards":["CONM1","CONM2","CMASS1","CMASS2","CMASS3","CMASS4","PMASS","PARAM_WTMASS"]},{"key":"pressure-force","title":"FORCE・PLOAD・PLOAD2・PLOAD4","summary":"FORCEは節点力、PLOAD系は面への荷重です。圧力は面積当たりの量なので、同じ数値を入力しても同じ合力にはなりません。対象面の指定方法と正方向が選択の要点です。","cards":["FORCE","PLOAD","PLOAD2","PLOAD4","LOAD","CASE_LOAD"]},{"key":"dynamic-loads","title":"LOAD・DLOAD・RLOAD・TLOAD","summary":"LOAD／DLOADはセットの組合せ、RLOADiは周波数依存、TLOADiは時間依存を担います。Case Controlで選択する命令と、Bulk Dataで定義するカードが同じ名前の場合も役割を区別します。","cards":["LOAD","DLOAD","RLOAD1","RLOAD2","TLOAD1","TLOAD2","CASE_LOAD","CASE_DLOAD","DAREA","SPCD"]},{"key":"eigensolvers","title":"EIGRL・EIGR・EIGC","summary":"EIGRLとEIGRは実固有値、EIGCは複素固有値の抽出条件です。SOL 110では実モードで縮約してから複素根を求めるので、両方の抽出条件を用意します。","cards":["EIGRL","EIGR","EIGC","CASE_METHOD","CASE_CMETHOD"]}];
